from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'docs/evidence/phiagent_benchmark_v0_1/quality_review_run3_v1_2_20261003'
rows=[]
def add(cid,ratings,notes,errors=None):
 p=json.loads((OUT/'packets'/f'{cid}-T1.json').read_text());keys=p['rating_keys'];reasons={}
 assert len(ratings)==len(notes)==len(keys)
 for k,(reason,span,evidence) in zip(keys,notes):
  assert not span or span in p['target_answer'],(cid,k,span)
  reasons[k]={'reason':reason,'span':span,'evidence':evidence}
 rows.append({'id':cid+'-T1','case_id':cid,'ratings':dict(zip(keys,ratings)),'reasons':reasons,'errors':errors or [],'review_level':'Codex targeted review','packet_sha256':hashlib.sha256((OUT/'packets'/f'{cid}-T1.json').read_bytes()).hexdigest(),'limits':'基于题设、完整回答与采集工具回执复核；不是人类专家验收，不补造当时执行证据。'})
